/// ACK error codes per MPD spec.
#[derive(Debug, Clone, Copy)]
pub enum MpdErrorCode {
    NotList = 1,
    Arg = 2,
    Password = 3,
    Permission = 4,
    UnknownCmd = 5,
    NoExist = 50,
    PlaylistMax = 51,
    System = 52,
    PlaylistLoad = 53,
    UpdateAlready = 54,
    PlayerSync = 55,
    Exist = 56,
}

/// A single key-value pair in an MPD response.
#[derive(Debug, Clone)]
pub struct MpdKv {
    pub key: String,
    pub value: String,
}

/// Helper to build kv pairs.
pub fn kv(key: &str, value: impl std::fmt::Display) -> MpdKv {
    MpdKv {
        key: key.to_string(),
        value: value.to_string(),
    }
}

/// Parsed MPD commands.
#[derive(Debug, Clone)]
pub enum MpdCommand {
    // Connection / session
    Ping,
    Close,
    Password(String),

    // Playback control
    Play(Option<u32>),   // position in playlist (optional)
    PlayId(Option<u32>), // song id (optional)
    Pause(Option<bool>), // toggle or explicit
    Stop,
    Next,
    Previous,
    Seek(u32, f64),   // songpos, time_secs
    SeekId(u32, f64), // songid, time_secs
    SeekCur(f64),     // relative or absolute seconds

    // Playback options
    SetVol(u8), // 0-100
    Volume(i8), // relative change
    Random(bool),
    Repeat(bool),
    Single(SingleMode),
    Consume(bool),

    // Status
    Status,
    Stats,
    CurrentSong,

    // Queue / playlist
    PlaylistInfo(Option<(u32, Option<u32>)>), // optional range
    PlaylistId(Option<u32>),
    Add(String),                // URI
    AddId(String, Option<u32>), // URI, optional position
    Delete(u32),                // position
    DeleteId(u32),              // song id
    Clear,
    Shuffle,
    Move(u32, u32), // from, to
    Swap(u32, u32), // pos1, pos2

    // Database / library
    ListAll(Option<String>), // optional path
    LsInfo(Option<String>),  // optional path
    Find(Vec<FilterExpr>),
    Search(Vec<FilterExpr>),
    List(String, Vec<FilterExpr>), // tag, optional filter
    Count(Vec<FilterExpr>),
    Update(Option<String>), // optional path

    // Output
    Outputs,
    EnableOutput(u32),
    DisableOutput(u32),
    ToggleOutput(u32),

    // Reflection
    Commands,
    NotCommands,
    TagTypes,
    UrlHandlers,
    Decoders,

    // Command lists
    CommandListBegin,
    CommandListOkBegin,
    CommandListEnd,

    // Idle / notify
    Idle(Vec<String>), // optional subsystems
    NoIdle,
}

#[derive(Debug, Clone)]
pub enum SingleMode {
    Off,
    On,
    OneShot,
}

#[derive(Debug, Clone)]
pub struct FilterExpr {
    pub tag: String,
    pub value: String,
}

